#!/usr/bin/env python3
"""Compile the actual visible C++20 fence and compare it with ownership enumeration.
Usage: python3 checker.py [article.mdx] [--sanitize]
"""
from pathlib import Path
import os
import shutil
import re
import subprocess
import sys
import tempfile
DEFAULT = Path(__file__).resolve().parents[1] / "src/content/docs/techniques/disjoint-candidate-sets-complement-lookup.mdx"
args = [arg for arg in sys.argv[1:] if arg != "--sanitize"]
article = Path(args[0]) if args else DEFAULT
blocks = re.findall(r"^```cpp\s*\n(.*?)^```\s*$", article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError("expected exactly one complete visible C++ fence")
TESTS = '#include <chrono>\n#include <cstdlib>\n#include <functional>\n#include <iostream>\n#include <random>\nusing Clock = std::chrono::steady_clock;\nstd::uint64_t tests = 0, assignments = 0;\nvoid require(bool condition, const char* message) {\n    ++tests;\n    if (!condition) { std::cerr << "FAIL " << message << \'\\n\'; std::exit(1); }\n}\nstruct Deal { std::array<CardMask,4> hands{}; CardMask hidden=0; };\n// Independent oracle: assign each unknown card an owner (three hands or hidden),\n// enforcing only counts and hidden-category counts while building complete deals.\nvoid visit_deals(int count, const std::array<CardMask,3>& categories,\n                 const std::array<int,4>& sizes, CardMask known,\n                 const std::function<void(const Deal&)>& visit) {\n    Deal deal; deal.hands[0]=known;\n    std::array<int,3> remain{sizes[1],sizes[2],sizes[3]}, secret{1,1,1};\n    std::vector<int> cards;\n    for(int c=0;c<count;++c) if(!(known&(CardMask{1}<<c))) cards.push_back(c);\n    auto dfs=[&](auto&& self,std::size_t at)->void {\n        if(at==cards.size()) { ++assignments; visit(deal); return; }\n        const CardMask bit=CardMask{1}<<cards[at];\n        for(int p=0;p<3;++p) if(remain[p]) {\n            --remain[p];deal.hands[p+1]|=bit;\n            self(self,at+1);\n            deal.hands[p+1]^=bit;++remain[p];\n        }\n        int category=0;while(!(categories[category]&bit)) ++category;\n        if(secret[category]) {\n            --secret[category];deal.hidden|=bit;\n            self(self,at+1);\n            deal.hidden^=bit;++secret[category];\n        }\n    };\n    dfs(dfs,0);\n}\nbool independent_rules(const Deal& deal,const std::array<HandRules,4>& rules,int count) {\n    for(int p=0;p<4;++p) {\n        for(int card=0;card<count;++card) {\n            CardMask bit=CardMask{1}<<card;\n            if((rules[p].present&bit) && !(deal.hands[p]&bit)) return false;\n            if((rules[p].absent&bit) && (deal.hands[p]&bit)) return false;\n        }\n        for(CardMask clause:rules[p].intersects) {\n            bool seen=false;\n            for(int card=0;card<count;++card)\n                if((clause&(CardMask{1}<<card)) && (deal.hands[p]&(CardMask{1}<<card))) seen=true;\n            if(!seen) return false;\n        }\n    }\n    return true;\n}\nHiddenCandidates oracle(const std::vector<Deal>& deals,const std::array<HandRules,4>& rules,\n                        int count,const std::array<CardMask,3>& categories) {\n    HiddenCandidates result;\n    for(const auto& deal:deals) if(independent_rules(deal,rules,count)) {\n        result.consistent=true;\n        for(int c=0;c<3;++c) result.possible[c]|=deal.hidden&categories[c];\n    }\n    return result;\n}\nvoid equal(const HiddenCandidates& a,const HiddenCandidates& b,const char* message) {\n    require(a.consistent==b.consistent && a.possible==b.possible,message);\n}\nCardMask mask_of(std::string cards) {\n    CardMask answer=0;for(char c:cards) answer|=CardMask{1}<<(c-\'A\');return answer;\n}\nstd::string identify(const HiddenCandidates& result) {\n    if(!result.consistent) return "!!!";\n    std::string answer;\n    for(CardMask mask:result.possible) answer += std::popcount(mask)==1?char(\'A\'+std::countr_zero(mask)):\'?\';\n    return answer;\n}\nstruct Observation { int player; CardMask query; int kind; CardMask shown; };\nvoid append(std::array<HandRules,4>& rules,const Observation& observation) {\n    auto& r=rules[observation.player];\n    if(observation.kind==0) r.absent|=observation.query;\n    if(observation.kind==1) r.intersects.push_back(observation.query);\n    if(observation.kind==2) r.present|=observation.shown;\n}\nvoid exhaustive_small() {\n    const std::array<CardMask,3> categories{3,12,48};\n    const std::array<int,4> sizes{0,1,1,1};\n    std::vector<Deal> deals;\n    visit_deals(6,categories,sizes,0,[&](const Deal& deal){deals.push_back(deal);});\n    require(deals.size()==48,"all six-card complete assignments");\n    for(int player=0;player<4;++player) for(CardMask query=1;query<64;++query) {\n        std::vector<Observation> events{{player,query,0,0},{player,query,1,0}};\n        for(int card=0;card<6;++card) if(query&(CardMask{1}<<card)) events.push_back({player,query,2,CardMask{1}<<card});\n        for(const auto& event:events) {\n            std::array<HandRules,4> rules;append(rules,event);\n            equal(infer_disjoint_hands(6,categories,sizes,0,rules),oracle(deals,rules,6,categories),"all one-response masks");\n        }\n    }\n    std::vector<Observation> events;\n    for(int player=1;player<4;++player) for(int a=0;a<2;++a) for(int b=2;b<4;++b) for(int c=4;c<6;++c) {\n        CardMask query=(CardMask{1}<<a)|(CardMask{1}<<b)|(CardMask{1}<<c);\n        events.push_back({player,query,0,0});events.push_back({player,query,1,0});\n        for(int card:{a,b,c}) events.push_back({player,query,2,CardMask{1}<<card});\n    }\n    require(events.size()==120,"all local response events");\n    for(const auto& first:events) for(const auto& second:events) {\n        std::array<HandRules,4> rules;append(rules,first);append(rules,second);\n        equal(infer_disjoint_hands(6,categories,sizes,0,rules),oracle(deals,rules,6,categories),"all two-response histories");\n    }\n    // Every fixed-card count and every known hand in a seven-card miniature.\n    const std::array<CardMask,3> other_categories{3,12,112};\n    for(CardMask known=0;known<128;++known) {\n        int rest=7-std::popcount(known)-3;\n        if(rest<0) continue;\n        for(int s1=0;s1<=rest;++s1) for(int s2=0;s2<=rest-s1;++s2) {\n            std::array<int,4> other_sizes{std::popcount(known),s1,s2,rest-s1-s2};\n            std::vector<Deal> all;\n            visit_deals(7,other_categories,other_sizes,known,[&](const Deal& deal){all.push_back(deal);});\n            std::array<HandRules,4> rules;\n            equal(infer_disjoint_hands(7,other_categories,other_sizes,known,rules),\n                  oracle(all,rules,7,other_categories),"all miniature card allocations and hand sizes");\n        }\n    }\n}\nvoid random_rules() {\n    std::mt19937 rng(2017);\n    const std::array<CardMask,3> categories{7,56,448};\n    const std::array<int,4> sizes{1,2,2,1};\n    for(int known_card=0;known_card<9;++known_card) {\n        CardMask known=CardMask{1}<<known_card;\n        std::vector<Deal> deals;\n        visit_deals(9,categories,sizes,known,[&](const Deal& deal){deals.push_back(deal);});\n        for(int trial=0;trial<120;++trial) {\n            std::array<HandRules,4> rules;\n            for(int event=0;event<8;++event) {\n                int player=int(rng()%4),kind=int(rng()%3);CardMask query=1+rng()%511;\n                append(rules,{player,query,kind,CardMask{1}<<(rng()%9)});\n            }\n            equal(infer_disjoint_hands(9,categories,sizes,known,rules),oracle(deals,rules,9,categories),"random independent ownership oracle");\n        }\n    }\n}\nbool history_fits(const Deal& deal,const std::vector<CardRound>& history) {\n    for(std::size_t turn=0;turn<history.size();++turn) {\n        CardMask suggestion=0;for(int card:history[turn].suggestion) suggestion|=CardMask{1}<<card;\n        for(std::size_t index=0;index<history[turn].responses.size();++index) {\n            int player=(int(turn)%4+int(index)+1)%4;\n            char response=history[turn].responses[index];\n            CardMask intersection=deal.hands[player]&suggestion;\n            if(response==\'-\' && intersection) return false;\n            if(response==\'*\' && !intersection) return false;\n            if(response!=\'-\' && response!=\'*\' && !(intersection&(CardMask{1}<<(response-\'A\')))) return false;\n        }\n    }\n    return true;\n}\nvoid original_cases() {\n    require(identify(infer_card_history(mask_of("BIPCF"),{{{0,6,12},"---"}}))=="AGM","official sample one");\n    require(identify(infer_card_history(mask_of("ABCDH"),{{{5,6,12},"M"},{{5,7,12},"-*"}}))=="E??","official sample two");\n    require(identify(infer_card_history(mask_of("ACMSD"),{{{1,6,18},"-G"},{{0,7,18},"--S"},{{2,9,18},"*"}}))=="???","official sample three");\n    const std::array<CardMask,3> categories{63,63<<6,511<<12};\n    CardMask known=mask_of("AGMNO");\n    auto started=Clock::now();\n    auto unconstrained=infer_card_history(known,{});\n    require(unconstrained.consistent,"maximum unconstrained feasible");\n    for(int c=0;c<3;++c) require(unconstrained.possible[c]==(categories[c]&~known),"maximum unconstrained candidates");\n    std::cout << "max_unconstrained_seconds=" << std::chrono::duration<double>(Clock::now()-started).count() << \'\\n\';\n    std::array<HandRules,4> hall;\n    for(int p=1;p<=3;++p) for(int i=0;i<50;++i) hall[p].intersects.push_back(mask_of("BH"));\n    started=Clock::now();\n    auto impossible=infer_disjoint_hands(21,categories,{5,5,4,4},known,hall);\n    require(!impossible.consistent && impossible.possible==std::array<CardMask,3>{},"maximum Hall contradiction and 150 clauses");\n    std::cout << "max_unsatisfiable_seconds=" << std::chrono::duration<double>(Clock::now()-started).count() << \'\\n\';\n    Deal truth;truth.hands[0]=known;truth.hidden=mask_of("BHP");\n    CardMask available=((CardMask{1}<<21)-1)^known^truth.hidden;\n    for(int p=1;p<=3;++p) {\n        int size=p==1?5:4;\n        for(int card=0;card<21 && size;++card) if(available&(CardMask{1}<<card)) {\n            truth.hands[p]|=CardMask{1}<<card;available^=CardMask{1}<<card;--size;\n        }\n    }\n    std::mt19937 rng(5050);\n    std::vector<CardRound> history;\n    for(int turn=0;turn<50;++turn) {\n        CardRound round{{int(rng()%6),6+int(rng()%6),12+int(rng()%9)},""};\n        CardMask suggestion=0;for(int card:round.suggestion) suggestion|=CardMask{1}<<card;\n        for(int step=1;step<=3;++step) {\n            int player=(turn%4+step)%4;CardMask hit=truth.hands[player]&suggestion;\n            if(!hit) round.responses+=\'-\';\n            else {round.responses+=(turn%4==0||player==0)?char(\'A\'+std::countr_zero(hit)):\'*\';break;}\n        }\n        history.push_back(round);\n    }\n    HiddenCandidates expected;\n    visit_deals(21,categories,{5,5,4,4},known,[&](const Deal& deal){\n        if(history_fits(deal,history)) {\n            expected.consistent=true;\n            for(int c=0;c<3;++c) expected.possible[c]|=deal.hidden&categories[c];\n        }\n    });\n    equal(infer_card_history(known,history),expected,"all full-size allocations for 50-round history");\n    require(expected.consistent,"generated history has a real witness");\n    std::array<HandRules,4> empty;\n    auto zero=infer_disjoint_hands(4,{1,2,12},{1,0,0,0},1,empty);\n    require(!zero.consistent && zero.possible==std::array<CardMask,3>{},"category with zero hidden candidates");\n    auto unique=infer_disjoint_hands(3,{1,2,4},{0,0,0,0},0,empty);\n    require(unique.consistent && unique.possible==std::array<CardMask,3>{1,2,4},"all secret, zero-sized hands");\n    empty[0].intersects.push_back(0);\n    require(!infer_disjoint_hands(3,{1,2,4},{0,0,0,0},0,empty).consistent,"empty existence clause is contradiction");\n}\ntemplate<class F> void invalid(F action) {\n    bool threw=false;try{action();}catch(const std::invalid_argument&){threw=true;}\n    require(threw,"invalid API must throw");\n}\nvoid invalid_cases() {\n    const std::array<CardMask,3> cats{3,12,48};\n    const std::array<int,4> sizes{0,1,1,1};\n    std::array<HandRules,4> rules;\n    invalid([&]{infer_disjoint_hands(2,cats,sizes,0,rules);});\n    invalid([&]{infer_disjoint_hands(22,cats,sizes,0,rules);});\n    invalid([&]{infer_disjoint_hands(6,{0,15,48},sizes,0,rules);});\n    invalid([&]{infer_disjoint_hands(6,{3,14,48},sizes,0,rules);});\n    invalid([&]{infer_disjoint_hands(6,{3,12,16},sizes,0,rules);});\n    invalid([&]{infer_disjoint_hands(6,{3,12,112},sizes,0,rules);});\n    invalid([&]{infer_disjoint_hands(6,cats,sizes,64,rules);});\n    invalid([&]{infer_disjoint_hands(6,cats,{0,-1,2,2},0,rules);});\n    invalid([&]{infer_disjoint_hands(6,cats,{0,1,1,2},0,rules);});\n    invalid([&]{infer_disjoint_hands(6,cats,{1,1,1,0},0,rules);});\n    invalid([&]{infer_disjoint_hands(20,{63,63<<6,255<<12},{1,6,5,5},1,rules);});\n    rules[1].absent=64;invalid([&]{infer_disjoint_hands(6,cats,sizes,0,rules);});rules={};\n    rules[1].present=64;invalid([&]{infer_disjoint_hands(6,cats,sizes,0,rules);});rules={};\n    rules[1].intersects={64};invalid([&]{infer_disjoint_hands(6,cats,sizes,0,rules);});rules={};\n    rules[1].intersects.assign(151,1);invalid([&]{infer_disjoint_hands(6,cats,sizes,0,rules);});\n    CardMask known=mask_of("AGMNO");\n    invalid([&]{infer_card_history(known,std::vector<CardRound>(51));});\n    invalid([&]{infer_card_history(known|2,{});});\n    invalid([&]{infer_card_history(CardMask{1}<<25,{});});\n    for(const CardRound& round:std::vector<CardRound>{\n        {{-1,6,12},"---"},{{21,6,12},"---"},{{6,0,12},"---"},\n        {{0,6,12},""},{{0,6,12},"----"},{{0,6,12},"-"},\n        {{0,6,12},"A-"},{{0,6,12},"?"},{{0,6,12},"*"},{{0,6,12},"B"}})\n        invalid([&]{infer_card_history(known,{round});});\n    invalid([&]{infer_card_history(known,{{{0,6,12},"A"},{{0,6,12},"A"}});});\n}\nint main() {\n    auto started=Clock::now();\n    exhaustive_small();random_rules();original_cases();invalid_cases();\n    std::uint64_t max_product=0, max_initial=0, max_secrets=0;\n    auto choose=[](int n,int k){std::uint64_t v=1;for(int i=1;i<=k;++i)v=v*(n-i+1)/i;return v;};\n    for(int remaining=0;remaining<=13;++remaining)\n      for(int s1=0;s1<=remaining;++s1) for(int s2=0;s2<=remaining-s1;++s2) {\n        std::array<std::uint64_t,3> counts{choose(remaining,s1),choose(remaining,s2),choose(remaining,remaining-s1-s2)};\n        std::sort(counts.begin(),counts.end());max_product=std::max(max_product,counts[0]*counts[1]);\n        max_initial=std::max(max_initial,choose(remaining+3,s1)+choose(remaining+3,s2)+choose(remaining+3,remaining-s1-s2));\n    }\n    for(int a=0;a<=16;++a) for(int b=0;b<=16-a;++b)\n        for(int c=0;c<=16-a-b;++c) max_secrets=std::max(max_secrets,std::uint64_t(a*b*c));\n    require(max_product==511225,"exhaustive hand-size worst pair product");\n    require(max_initial==19449,"initial candidate count upper bound");\n    require(max_secrets==150,"secret category product upper bound");\n    std::cout<<"checks="<<tests<<" complete_assignments="<<assignments\n             <<" max_pair_product="<<max_product<<" pair_upper_bound="<<150*max_product\n             <<" total_seconds="<<std::chrono::duration<double>(Clock::now()-started).count()<<\'\\n\';\n}\n'
with tempfile.TemporaryDirectory(prefix="flowchartcp-clue-") as directory:
    source = Path(directory) / "check.cpp"
    binary = Path(directory) / "check"
    source.write_text(blocks[0] + "\n" + TESTS)
    flags = ["-std=c++20", "-O2", "-Wall", "-Wextra", "-Werror"]
    environment = os.environ.copy()
    if "--sanitize" in sys.argv:
        flags += ["-g", "-fsanitize=address,undefined", "-fno-omit-frame-pointer"]
        environment["ASAN_OPTIONS"] = "detect_leaks=0"
    compiler = os.environ.get("CXX") or shutil.which("g++") or shutil.which("clang++") or "c++"
    subprocess.run([compiler, *flags, str(source), "-o", str(binary)], check=True, timeout=120)
    subprocess.run([str(binary)], check=True, env=environment, timeout=180)
